#include "core.h"

// MD E12: generated by tools/make_engine.py. Each key holds its own machine,
// chosen with Shift and the first encoder, and that machine's eight controls
// (kit.h), which the SDK saves with the project. The sound is in the voice
// modules: E12-BD (voices/e12.hpp), E12-SD (voices/e12.hpp), E12-HT (voices/e12.hpp), E12-LT (voices/e12.hpp), E12-CP (voices/e12.hpp), E12-RS (voices/e12.hpp), E12-CB (voices/e12.hpp), E12-CH (voices/e12.hpp), E12-OH (voices/e12.hpp), E12-RC (voices/e12.hpp), E12-CC (voices/e12.hpp), E12-BR (voices/e12.hpp), E12-TA (voices/e12.hpp), E12-TR (voices/e12.hpp), E12-SH (voices/e12.hpp), E12-BC (voices/e12.hpp).
namespace mde12 {
void drum_defaults(u32 key, opxy::u8* model, opxy::u8* controls) {
    const u32 k = key >= 53 && key < 53 + kit::keys ? key - 53 : 0;
    *model = kit::key_model[k];
    for (u32 c = 0; c < 8; ++c) controls[c] = kit::key_values[k][c];
}
const char* model_name(u32 model) { return kit::model[model < kit::models ? model : 0].name; }
const char* parameter_name(u32 model, u32 slot) {
    return slot < 8 ? kit::model[model < kit::models ? model : 0].labels[slot] : "";
}
u32 parameter_count(u32 model) { return kit::model[model < kit::models ? model : 0].count; }

inline void begin_member(Voice& voice, Shared& shared) {
    switch (voice.machine) {
    case 0: md::e12_bd::reset(voice.u.m0, shared.common, voice.owner); break;
    case 1: md::e12_sd::reset(voice.u.m1, shared.common, voice.owner); break;
    case 2: md::e12_ht::reset(voice.u.m2, shared.common, voice.owner); break;
    case 3: md::e12_lt::reset(voice.u.m3, shared.common, voice.owner); break;
    case 4: md::e12_cp::reset(voice.u.m4, shared.common, voice.owner); break;
    case 5: md::e12_rs::reset(voice.u.m5, shared.common, voice.owner); break;
    case 6: md::e12_cb::reset(voice.u.m6, shared.common, voice.owner); break;
    case 7: md::e12_ch::reset(voice.u.m7, shared.common, voice.owner); break;
    case 8: md::e12_oh::reset(voice.u.m8, shared.common, voice.owner); break;
    case 9: md::e12_rc::reset(voice.u.m9, shared.common, voice.owner); break;
    case 10: md::e12_cc::reset(voice.u.m10, shared.common, voice.owner); break;
    case 11: md::e12_br::reset(voice.u.m11, shared.common, voice.owner); break;
    case 12: md::e12_ta::reset(voice.u.m12, shared.common, voice.owner); break;
    case 13: md::e12_tr::reset(voice.u.m13, shared.common, voice.owner); break;
    case 14: md::e12_sh::reset(voice.u.m14, shared.common, voice.owner); break;
    case 15: md::e12_bc::reset(voice.u.m15, shared.common, voice.owner); break;
    default: return;
    }
    switch (voice.machine) {
    case 0: md::e12_bd::trigger(voice.u.m0, shared.common); break;
    case 1: md::e12_sd::trigger(voice.u.m1, shared.common); break;
    case 2: md::e12_ht::trigger(voice.u.m2, shared.common); break;
    case 3: md::e12_lt::trigger(voice.u.m3, shared.common); break;
    case 4: md::e12_cp::trigger(voice.u.m4, shared.common); break;
    case 5: md::e12_rs::trigger(voice.u.m5, shared.common); break;
    case 6: md::e12_cb::trigger(voice.u.m6, shared.common); break;
    case 7: md::e12_ch::trigger(voice.u.m7, shared.common); break;
    case 8: md::e12_oh::trigger(voice.u.m8, shared.common); break;
    case 9: md::e12_rc::trigger(voice.u.m9, shared.common); break;
    case 10: md::e12_cc::trigger(voice.u.m10, shared.common); break;
    case 11: md::e12_br::trigger(voice.u.m11, shared.common); break;
    case 12: md::e12_ta::trigger(voice.u.m12, shared.common); break;
    case 13: md::e12_tr::trigger(voice.u.m13, shared.common); break;
    case 14: md::e12_sh::trigger(voice.u.m14, shared.common); break;
    case 15: md::e12_bc::trigger(voice.u.m15, shared.common); break;
    default: break;
    }
}

inline void initialize(Voice& voice, Shared&, u32 owner) {
    voice.machine = 0;
    voice.next = 0;
    voice.owner = owner;
    voice.pending = 0;
}
inline void start(Voice& voice, Shared&, u32) { voice.pending = 1; }
inline void destroy(Voice&, Shared&, u32) {}
inline void drum_select(Voice& voice, Shared&, u32, u32 model) { voice.next = model < kit::models ? model : 0; }

// The machines are voiced at middle C and tuned by their own PTCH, as on the
// original, so the note's pitch is not used.
inline void render(Voice& voice, Shared& shared, u32, opxy::Output output, opxy::Parameters parameters, opxy::Pitch) {
    if (voice.pending || voice.next != voice.machine) {
        voice.pending = 0;
        voice.machine = voice.next;
        begin_member(voice, shared);
    }
    i32 own[8];
    kit::controls(voice.machine, parameters, own);
    u32 tuned[opxy::block_frames];
    for (unsigned i = 0; i < opxy::block_frames; ++i) tuned[i] = ::md::kit::middle_c;
    switch (voice.machine) {
    case 0: md::e12_bd::render(voice.u.m0, shared.common, output, own, tuned); break;
    case 1: md::e12_sd::render(voice.u.m1, shared.common, output, own, tuned); break;
    case 2: md::e12_ht::render(voice.u.m2, shared.common, output, own, tuned); break;
    case 3: md::e12_lt::render(voice.u.m3, shared.common, output, own, tuned); break;
    case 4: md::e12_cp::render(voice.u.m4, shared.common, output, own, tuned); break;
    case 5: md::e12_rs::render(voice.u.m5, shared.common, output, own, tuned); break;
    case 6: md::e12_cb::render(voice.u.m6, shared.common, output, own, tuned); break;
    case 7: md::e12_ch::render(voice.u.m7, shared.common, output, own, tuned); break;
    case 8: md::e12_oh::render(voice.u.m8, shared.common, output, own, tuned); break;
    case 9: md::e12_rc::render(voice.u.m9, shared.common, output, own, tuned); break;
    case 10: md::e12_cc::render(voice.u.m10, shared.common, output, own, tuned); break;
    case 11: md::e12_br::render(voice.u.m11, shared.common, output, own, tuned); break;
    case 12: md::e12_ta::render(voice.u.m12, shared.common, output, own, tuned); break;
    case 13: md::e12_tr::render(voice.u.m13, shared.common, output, own, tuned); break;
    case 14: md::e12_sh::render(voice.u.m14, shared.common, output, own, tuned); break;
    case 15: md::e12_bc::render(voice.u.m15, shared.common, output, own, tuned); break;
    default: for (unsigned i = 0; i < opxy::block_frames; ++i) output[i] = 0; break;
    }
}
}
